```javascript
const A = 5, B = 3, C = 3, threshold = 6;
const coalitions = [
  { members: ["A", "B"], sum: A + B },
  { members: ["A", "C"], sum: A + C },
  { members: ["B", "C"], sum: B + C },
  { members: ["A", "B", "C"], sum: A + B + C }
];
const minimal = [];
for (const c of coalitions) {
  if (c.sum >= threshold) {
    let isMinimal = true;
    for (let i = 0; i < c.members.length; i++) {
      const without = c.members.reduce((sum, m, idx) => (idx !== i ? sum + (m === "A" ? A : m === "B" ? B : C) : sum), 0);
      if (without >= threshold) isMinimal = false;
    }
    if (isMinimal) minimal.push(c.members.join(" and "));
  }
}
return "Minimal winning coalitions: " + minimal.join(", ") + ".";
```

